use angzarr_proto::v1::{
    command_page, Command, CommandBook, CommandPage, Cover, EventBook, EventPage, EventRef,
    Handling, Uuid,
};
use angzarr_router::error::CodedError;
use angzarr_router::pb::PolicyReaction;
use angzarr_router::policy::PolicyDispatch;
use prost_types::Any;

use super::check::{check_policy_command, Checked, Malformed};
use super::dead_letter::{self, Cause, Component, DeadLetterLog};
use super::domain::Domain;
use super::handler::{Committed, Handler};
use super::markup::{self, CommandContext, Commands, PolicyContext, TypeName};
use super::payload::{type_name, Payload};
use super::registry::Registry;

// ---------------------------------------------------------------- policies

/// A policy's translated refusal fact on the wire (`OnRefusedResponse.fact`,
/// set), as the kernel takes it (decision 14.42): its payload alone. A fact
/// that is more than a payload is the policy's bug, refused INTERNAL: one
/// that sets its own cover or handling (`COORDINATOR_REASON_REFUSAL_FACT_ADDRESSED`), with no
/// page (`COORDINATOR_REASON_REFUSAL_FACT_NO_PAGE`), that sets its own identity
/// (`COORDINATOR_REASON_REFUSAL_FACT_IDENTIFIED`), or whose page is not a fact with a payload
/// (`COORDINATOR_REASON_REFUSAL_FACT_NOT_A_FACT`). An unset fact is no translation, and the
/// kernel passes the refusal through. The kernel addresses and identifies
/// every refusal fact itself.
pub fn translated(fact: CommandBook) -> Result<Any, CodedError> {
    use super::reasons::CoordinatorReason;
    let refused = |code: &str| super::route::internal(code, []);
    if fact.cover.is_some() || fact.handling.is_some() {
        return Err(refused(
            CoordinatorReason::RefusalFactAddressed.as_str_name(),
        ));
    }
    let page = fact
        .page
        .ok_or_else(|| refused(CoordinatorReason::RefusalFactNoPage.as_str_name()))?;
    if page.command_id.is_some()
        || page.correlation_id.is_some()
        || page.causation_id.is_some()
        || page.fact_origin.is_some()
    {
        return Err(refused(
            CoordinatorReason::RefusalFactIdentified.as_str_name(),
        ));
    }
    match page.body {
        Some(command_page::Body::Fact(angzarr_proto::v1::Fact {
            payload: Some(payload),
        })) => Ok(payload),
        _ => Err(refused(
            CoordinatorReason::RefusalFactNotAFact.as_str_name(),
        )),
    }
}

/// A policy's `reactions` to `source`, checked and stamped by the kernel
/// per triggering page ([`check_reaction`], the page the reaction's
/// `trigger_sequence` names giving the correlation), its commands in
/// reaction order then command order. A reaction naming no page of
/// `source` is checked against no correlation.
///
/// Then each command's **identity**: its own `command_id` and
/// `causation_id`, where set, are the ones the kernel stamps on it, the id
/// derived from `trigger`, the policy `component` and the command's index
/// in the whole answer ([`ids::policy_command_id`](super::ids::policy_command_id)),
/// and `trigger`; any other is
/// `COORDINATOR_REASON_POLICY_COMMAND_OTHER_IDENTITY`, naming its domain,
/// type and the `field` (decision 14.48, amended), INTERNAL.
pub(crate) fn check_reactions(
    output_domain: &str,
    source: &EventBook,
    reactions: Vec<PolicyReaction>,
    component: &str,
    trigger: &EventRef,
) -> Result<Vec<CommandBook>, CodedError> {
    use super::reasons::{args, CoordinatorReason};
    let stream = source.cover.clone().unwrap_or_default();
    let mut commands = Vec::new();
    for reaction in reactions {
        let correlation = source
            .pages
            .iter()
            .find(|page| page.sequence == reaction.trigger_sequence)
            .and_then(|page| page.meta.as_ref())
            .and_then(|meta| meta.correlation_id.as_ref());
        commands.extend(check_reaction(
            output_domain,
            &stream,
            correlation,
            reaction.commands,
        )?);
    }
    for (index, command) in (0..).zip(&commands) {
        let Some(page) = &command.page else {
            continue;
        };
        let other_id = page.command_id.as_ref().is_some_and(|id| {
            super::ids::policy_command_id(trigger, component, index).as_ref() != Ok(id)
        });
        let other_cause = page.causation_id.as_ref().is_some_and(|c| c != trigger);
        let field = match (other_id, other_cause) {
            (true, _) => "command_id",
            (false, true) => "causation_id",
            (false, false) => continue,
        };
        return Err(super::route::internal(
            CoordinatorReason::PolicyCommandOtherIdentity.as_str_name(),
            named(command)
                .into_iter()
                .chain([(args::FIELD.to_string(), field.to_string())]),
        ));
    }
    Ok(commands)
}

/// A policy's command as its refusal names it: its domain and its
/// payload's type.
fn named(command: &CommandBook) -> [(String, String); 2] {
    use super::reasons::args;
    use angzarr_router::error::extras;
    let domain = command.cover.as_ref().map_or("", |c| c.domain.as_str());
    let command_type = command
        .page
        .as_ref()
        .and_then(|p| match &p.body {
            Some(command_page::Body::Command(c)) => c.payload.as_ref(),
            Some(command_page::Body::Fact(f)) => f.payload.as_ref(),
            None => None,
        })
        .map_or("", |p| type_name(&p.type_url));
    [
        (args::DOMAIN.to_string(), domain.to_string()),
        (extras::COMMAND_TYPE.to_string(), command_type.to_string()),
    ]
}

/// One triggering event's commands, as a policy answered them, checked and
/// stamped by the kernel (decision 14.42), every command against these
/// rules; one failure refuses the whole answer as the policy's bug,
/// INTERNAL:
/// - **destination**: its cover's domain is `output_domain`
///   (`COORDINATOR_REASON_POLICY_COMMAND_OUTSIDE_DESTINATION`, naming both domains);
/// - **edition**: unset, or the `trigger` stream's; an unset one is stamped
///   with the trigger's (`COORDINATOR_REASON_POLICY_COMMAND_OUTSIDE_EDITION`, naming both);
/// - **root**: named, with bytes (`COORDINATOR_REASON_POLICY_COMMAND_NO_ROOT`);
/// - **handling**: none, an empty one being none: a reaction command's
///   target stamps its own head (`COORDINATOR_REASON_POLICY_COMMAND_WITH_HANDLING`,
///   naming its domain and type; decision 14.48);
/// - **a command**: a policy's business code emits Commands only, its
///   refusal facts coming from OnRefused: not a Fact
///   (`COORDINATOR_REASON_POLICY_COMMAND_IS_FACT`), and with no
///   `fact_origin` (`COORDINATOR_REASON_POLICY_COMMAND_FACT_ORIGIN`), each
///   naming its domain and type (decision 14.48, amended);
/// - **correlation**: unset, or the trigger's, `correlation`
///   (`COORDINATOR_REASON_POLICY_COMMAND_OTHER_CORRELATION`).
///
/// Its identity is held to its stamp by [`check_reactions`], which knows
/// its index in the whole answer.
pub(crate) fn check_reaction(
    output_domain: &str,
    trigger: &Cover,
    correlation: Option<&Uuid>,
    mut commands: Vec<CommandBook>,
) -> Result<Vec<CommandBook>, CodedError> {
    use super::reasons::{args, CoordinatorReason};
    let domain = |c: &CommandBook| {
        c.cover
            .as_ref()
            .map_or("", |c| c.domain.as_str())
            .to_string()
    };
    if let Some(stray) = commands.iter().find(|c| domain(c) != output_domain) {
        return Err(super::route::internal(
            CoordinatorReason::PolicyCommandOutsideDestination.as_str_name(),
            [
                (args::EXPECTED_DOMAIN.to_string(), output_domain.to_string()),
                (args::ACTUAL_DOMAIN.to_string(), domain(stray)),
            ],
        ));
    }
    let edition = trigger.edition.clone().filter(|e| !e.is_empty());
    for command in &mut commands {
        let naming = || named(command);
        let named = command
            .cover
            .as_ref()
            .and_then(|c| c.root.as_ref())
            .is_some_and(|r| !r.value.is_empty());
        if !named {
            return Err(super::route::internal(
                CoordinatorReason::PolicyCommandNoRoot.as_str_name(),
                naming(),
            ));
        }
        if command
            .handling
            .as_ref()
            .is_some_and(|h| *h != Handling::default())
        {
            return Err(super::route::internal(
                CoordinatorReason::PolicyCommandWithHandling.as_str_name(),
                naming(),
            ));
        }
        let page = command.page.as_ref();
        let refused = match page.and_then(|p| p.body.as_ref()) {
            Some(command_page::Body::Fact(_)) => Some(CoordinatorReason::PolicyCommandIsFact),
            _ if page.is_some_and(|p| p.fact_origin.is_some()) => {
                Some(CoordinatorReason::PolicyCommandFactOrigin)
            }
            _ => None,
        };
        if let Some(reason) = refused {
            return Err(super::route::internal(reason.as_str_name(), naming()));
        }
        let carried = command
            .page
            .as_ref()
            .and_then(|p| p.correlation_id.as_ref());
        if let (Some(carried), Some(trigger)) = (carried, correlation) {
            if carried != trigger {
                return Err(super::route::internal(
                    CoordinatorReason::PolicyCommandOtherCorrelation.as_str_name(),
                    naming(),
                ));
            }
        }
        let cover = command.cover.get_or_insert_with(Cover::default);
        match cover.edition.as_deref().filter(|e| !e.is_empty()) {
            None => cover.edition = edition.clone(),
            Some(named) if Some(named) != edition.as_deref() => {
                return Err(super::route::internal(
                    CoordinatorReason::PolicyCommandOutsideEdition.as_str_name(),
                    [
                        (
                            args::EXPECTED_EDITION.to_string(),
                            edition.clone().unwrap_or_default(),
                        ),
                        (args::ACTUAL_EDITION.to_string(), named.to_string()),
                    ],
                ));
            }
            Some(_) => {}
        }
    }
    Ok(commands)
}

/// What a policy sends commands to ([`Policy::Target`]): a domain known by
/// its name and the commands it decides alone, wherever it is decided.
/// Every [`Domain`] is one, so a policy targets a domain registered here
/// by its own type; a domain a coordinator elsewhere owns
/// ([`Registry::remote`](super::Registry::remote)), or one served by a
/// child process, is targeted by a command set written for it, with no
/// stand-in aggregate:
///
/// ```ignore
/// pub struct Bank;
///
/// impl CommandTarget for Bank {
///     const DOMAIN: &'static str = "bank";
///     fn command_types() -> Vec<String> {
///         vec![TypeName::of::<wire::Deposit>().full_name()]
///     }
/// }
///
/// impl Decides<Deposit> for Bank {} // what `Commands<Bank>::to` takes
/// ```
pub trait CommandTarget: 'static {
    /// The domain's name: the `Cover.domain` of the streams its commands
    /// go to. Not `NAME`, so a domain's own [`Domain::NAME`] is never
    /// ambiguous where both traits are in scope.
    const DOMAIN: &'static str;

    /// The full names (`"pkg.v1.Deposit"`) of the commands it decides: the
    /// refused commands a policy that answers refusals and names no
    /// [`Policy::TRANSLATES`] answers.
    fn command_types() -> Vec<String>;
}

/// A domain is the target of its own commands: its name, and its
/// [`Domain::Command`]'s types.
impl<D: Domain> CommandTarget for D {
    const DOMAIN: &'static str = D::NAME;

    fn command_types() -> Vec<String> {
        <D::Command as Payload>::type_urls()
            .iter()
            .map(|url| type_name(url).to_string())
            .collect()
    }
}

/// What a policy reads events of ([`Policy::Source`]): a domain known by
/// its name and the events it records, wherever it is decided. Every
/// [`Domain`] is one, so a policy is sourced from a domain registered here
/// by its own type; a domain served by a child process (registered by
/// [`Registry::command_handler`](super::Registry::command_handler), not
/// written in Rust) is named by an event set written for it, with no
/// stand-in aggregate:
///
/// ```ignore
/// pub struct Player;
///
/// impl EventSource for Player {
///     const DOMAIN: &'static str = "player";
///     fn event_types() -> Vec<String> {
///         vec![TypeName::of::<wire::MoveDecided>().full_name()]
///     }
/// }
///
/// impl Ingests<Seated> for Player {} // what an `#[on_refused]` may answer
/// ```
///
/// A remote domain ([`Registry::remote`](super::Registry::remote)) is
/// never a policy's source here: its events are its coordinator's, and
/// registering such a policy is refused
/// ([`Misconfigured::RemoteSource`](super::Misconfigured::RemoteSource)).
///
/// Its `DOMAIN` is [`CommandTarget::DOMAIN`]'s twin: for a type that is
/// both (every [`Domain`]), name the one meant,
/// `<Counter as EventSource>::DOMAIN`.
pub trait EventSource: 'static {
    /// The domain's name: the `Cover.domain` of the streams whose events
    /// the policy reads, and to which its refusal facts go.
    const DOMAIN: &'static str;

    /// The full names (`"pkg.v1.MoveDecided"`) of the events it records:
    /// the events a policy that names no [`Policy::EVENTS`] reads.
    fn event_types() -> Vec<String>;
}

/// A domain is the source of its own events: its name, and its
/// [`Domain::Event`]'s types.
impl<D: Domain> EventSource for D {
    const DOMAIN: &'static str = D::NAME;

    fn event_types() -> Vec<String> {
        <D::Event as Payload>::type_urls()
            .iter()
            .map(|url| type_name(url).to_string())
            .collect()
    }
}

/// Event → commands: one source domain, one target domain, and the
/// commands each source event is owed, each with the root of the target
/// stream it is for. Stateless: what it owes is a function of the event.
///
/// **Policies should not fail for business reasons**: they react to events
/// the application's own domains created, so an `Err` from
/// [`Policy::on_event`] is a bug. It fails the step as
/// [`StepError::PolicyFailed`](super::StepError::PolicyFailed), a defect,
/// dead-lettered by its code and args, its position moved past the
/// trigger (unless the kernel says to stay:
/// [`Kernel::on_policy_bug`](super::Kernel::on_policy_bug)).
/// Each command is decided by its target and may be refused: a policy that
/// answers refusals ([`Policy::ANSWERS_REFUSALS`], every marked-up one)
/// delivers its refusal fact to the source ([`Policy::on_refused`]);
/// another's refused command fails its step
/// ([`Failure::Downstream`](super::Failure::Downstream) with
/// [`StepError::Rejected`](super::StepError::Rejected)), the step
/// dead-lettered and its position moved past it.
pub trait Policy: Send + Sync + 'static {
    /// The policy's name, stable across releases and never empty: the
    /// `component` its commands' ids are derived from, and its position's
    /// handler. Changing it changes every derived command id.
    ///
    /// The ids name nothing else of the policy: not a rules version, not
    /// its code. A re-run over a trigger it already handled (a redelivery,
    /// a resume) re-derives the same ids and deduplicates, even if the
    /// policy now decides differently. Repairs are new commands with new
    /// ids, appended after what the old code wrote; history is never
    /// rewritten (angzarr decision 13.4).
    const NAME: &'static str;
    /// The one domain whose events it handles, and to which it delivers
    /// its refusal facts, known by its name and its events
    /// ([`EventSource`]): a domain here, by its own type, or a
    /// child-hosted one's event set.
    type Source: EventSource;
    /// The one domain it sends commands to, known by its name and its
    /// commands ([`CommandTarget`]): a domain here, by its own type, or a
    /// remote one's command set.
    type Target: CommandTarget;
    /// The events it handles, in marker order (a marked-up policy's); empty
    /// for a hand-written one, which reads every event of its source.
    const EVENTS: &'static [TypeName] = &[];
    /// The commands whose refusals it translates: those its
    /// `#[on_refused]` callbacks name, in marker order.
    const TRANSLATES: &'static [TypeName] = &[];
    /// Whether a refusal of its command is answered by its refusal fact to
    /// the source ([`Policy::on_refused`]): angzarr's refusal flow, every
    /// marked-up policy's. A policy that does not has its refused command
    /// fail the step.
    const ANSWERS_REFUSALS: bool = false;

    /// The commands this policy sends for `event` (an event of its source,
    /// packed), each with its target stream's root; `None` for an event it
    /// does not handle; or why it cannot answer the event, a bug (an event
    /// that cannot happen, or one of a type it handles that does not
    /// decode): its step fails as
    /// [`StepError::PolicyFailed`](super::StepError::PolicyFailed), is
    /// dead-lettered as a handler's bug (its reason
    /// `ROUTER_REASON_UNHANDLED_HANDLER_ERROR`, the error's code and args
    /// its `cause`), and its position moves past the event.
    /// Policies should not fail for business reasons: they react to events
    /// the application's own domains created, so an `Err` is a bug.
    fn on_event(
        &self,
        event: &Any,
        ctx: &PolicyContext,
    ) -> Result<Option<Commands<Self::Target>>, Report>;

    /// angzarr's `PolicyService.OnRefused`: the refusal fact's payload for
    /// the policy's source, packed. Pass-through by default: angzarr's
    /// `CommandRefused { command, refusal, trigger }`, `refusal` the
    /// response's object still packed, `trigger` the triggering event's
    /// `EventRef`. A marked-up policy's `#[on_refused]` callback translates
    /// instead. The chain addresses it to the trigger's stream and stamps
    /// its identity.
    ///
    /// `ctx` is the refused command's context, whole, as its target's
    /// handler was handed it (angzarr-router's `command_context` of the
    /// delivery): the target's cover, its next sequence and whether it had
    /// history, the sequence and resolution the command was decided under,
    /// the conflict under AGGREGATE_HANDLES, and the command's identity. A
    /// refused command of a type a marked-up policy translates that does
    /// not decode is its error too. An error is a bug, as `on_event`'s is: the step fails as
    /// [`StepError::PolicyFailed`](super::StepError::PolicyFailed), is
    /// dead-lettered by the error's code and args, and the policy's
    /// position moves past the trigger.
    fn on_refused(
        &self,
        refusal: &markup::v1::Refusal,
        ctx: &CommandContext,
    ) -> Result<Any, Report> {
        let _ = ctx;
        Ok(markup::pass_through(refusal))
    }
}

/// Event → read model. Produces nothing. Read models are replayed from the
/// stream on every read ([`Stream::dispatch`](super::Stream::dispatch) from 0).
pub trait Projection<D: Domain> {
    fn project(&mut self, committed: &Committed<'_, D>);
}

// ---------------------------------------------------------------- dispatch

/// One command a policy owes one target, before the kernel books it.
/// Built only by the kernel, from a committed event.
pub struct Order {
    pub(crate) policy: String,
    pub(crate) cover: Cover,
    pub(crate) command: Any,
    pub(crate) trigger: EventRef,
    pub(crate) index: u32,
    pub(crate) correlation_id: Uuid,
}

impl Order {
    /// The target's stream.
    pub fn cover(&self) -> &Cover {
        &self.cover
    }

    /// The command, packed.
    pub fn command(&self) -> &Any {
        &self.command
    }

    /// The source event: the command's causation (not its events').
    pub fn trigger(&self) -> &EventRef {
        &self.trigger
    }

    /// The command's index among those the trigger set off for this
    /// policy, in order.
    pub fn index(&self) -> u32 {
        self.index
    }

    /// The trigger's correlation, which the command keeps.
    pub fn correlation_id(&self) -> &Uuid {
        &self.correlation_id
    }

    /// The order as a book, checked through the kernel's policy entry:
    /// the target's cover, the command packed as `Any`, no ids, no
    /// handling. Malformed only by a bug (a policy or kernel one).
    pub(crate) fn check(&self, registry: &Registry) -> Result<Checked, Malformed> {
        check_policy_command(
            self.book(),
            registry,
            self.trigger.clone(),
            &self.policy,
            self.index,
            self.correlation_id.clone(),
        )
    }

    /// [`Order::check`], writing a dead letter for a malformed book: only a
    /// bug makes one.
    pub(crate) fn check_logged(
        &self,
        registry: &Registry,
        dead_letters: &dyn DeadLetterLog,
    ) -> Result<Checked, Malformed> {
        self.check(registry).inspect_err(|malformed| {
            dead_letter::write(
                dead_letters,
                Letter::RejectedCommand(self.book()),
                Component::policy(&self.policy),
                Cause::Malformed(malformed),
            )
        })
    }

    /// The order as the kernel books it: the target's cover, the command
    /// packed as `Any`, no ids, no handling.
    pub(crate) fn book(&self) -> CommandBook {
        CommandBook {
            cover: Some(self.cover.clone()),
            page: Some(CommandPage {
                body: Some(command_page::Body::Command(Command {
                    payload: Some(self.command.clone()),
                })),
                ..CommandPage::default()
            }),
            handling: None,
        }
    }
}

/// A policy as a [`Handler`] of its source: each committed event becomes
/// one [`Order`] per command, handed to `sink` in order. An event the policy
/// fails on hands over nothing, and is dead-lettered to `dead_letters` as
/// the kernel dead-letters a policy's failed step: a handler's bug, its
/// error's code and args the `cause`.
pub fn policy<'p, P: Policy, F: FnMut(Order)>(
    policy: &'p P,
    dead_letters: &'p dyn DeadLetterLog,
    sink: F,
) -> PolicyHandler<'p, P, F> {
    PolicyHandler {
        policy,
        dead_letters,
        sink,
    }
}

/// A projection as a [`Handler`].
pub fn projection<P>(projection: &mut P) -> Projector<'_, P> {
    Projector(projection)
}

/// See [`policy`].
pub struct PolicyHandler<'p, P, F> {
    policy: &'p P,
    dead_letters: &'p dyn DeadLetterLog,
    sink: F,
}

/// See [`projection`].
pub struct Projector<'p, P>(&'p mut P);

impl<P: Policy, F: FnMut(Order)> Handler<P::Source> for PolicyHandler<'_, P, F>
where
    P::Source: Domain,
{
    fn handle(&mut self, committed: &Committed<'_, P::Source>) {
        let ctx = PolicyContext::new(
            committed.event_ref(),
            committed.envelope.correlation_id().clone(),
            committed.envelope.recorded_at(),
        );
        let event = committed.event().to_any();
        let commands = match self.policy.on_event(&event, &ctx) {
            Ok(Some(commands)) => commands,
            Ok(None) => return,
            Err(failure) => {
                let trigger = EventBook {
                    cover: Some(committed.cover.clone()),
                    pages: vec![EventPage {
                        sequence: committed.sequence(),
                        payload: Some(event),
                        ..EventPage::default()
                    }],
                    ..EventBook::default()
                };
                dead_letter::write(
                    self.dead_letters,
                    Letter::RejectedEvents(trigger),
                    Component::policy(P::NAME),
                    Cause::PolicyFailed(&failure),
                );
                return;
            }
        };
        let target = <P::Target as CommandTarget>::DOMAIN;
        for order in orders(
            P::NAME,
            target,
            committed.cover,
            &ctx,
            commands.into_orders(),
        ) {
            (self.sink)(order);
        }
    }
}

impl<D: Domain, P: Projection<D>> Handler<D> for Projector<'_, P> {
    fn handle(&mut self, committed: &Committed<'_, D>) {
        self.0.project(committed)
    }
}

/// The stream a policy's command for `root` goes to, for a source event in
/// `source`: the target domain's, in the source's edition.
pub fn target_cover<P: Policy>(source: &Cover, root: &Uuid) -> Cover {
    cover_in(<P::Target as CommandTarget>::DOMAIN, source, root)
}

/// `domain`'s stream at `root`, in `source`'s edition.
pub(crate) fn cover_in(domain: &str, source: &Cover, root: &Uuid) -> Cover {
    Cover {
        domain: domain.to_string(),
        root: Some(root.clone()),
        edition: source.edition.clone(),
    }
}

/// The orders a policy named `policy` owes for the event `ctx` names in
/// `source`, its `commands` to `target`'s streams in order, the `index`th
/// command's index `index`.
pub(crate) fn orders(
    policy: &str,
    target: &str,
    source: &Cover,
    ctx: &PolicyContext,
    commands: Vec<(Uuid, Any)>,
) -> Vec<Order> {
    (0..)
        .zip(commands)
        .map(|(index, (root, command))| Order {
            policy: policy.to_string(),
            cover: cover_in(target, source, &root),
            command,
            trigger: ctx.trigger().clone(),
            index,
            correlation_id: ctx.correlation_id().clone(),
        })
        .collect()
}

/// The orders policy `policy` owes for `trigger` (in `correlation_id`):
/// the answer, `books`, each the target's stream (the kernel held it to
/// the trigger's edition, a named root and the trigger's correlation,
/// [`check_reaction`]) and its command, in order.
pub(crate) fn answered(
    policy: &str,
    trigger: &EventRef,
    correlation_id: &Uuid,
    books: Vec<CommandBook>,
) -> Vec<Order> {
    (0..)
        .zip(books)
        .map(|(index, book)| Order {
            policy: policy.to_string(),
            cover: book.cover.unwrap_or_default(),
            command: match book.page.and_then(|p| p.body) {
                Some(command_page::Body::Command(command)) => command.payload.unwrap_or_default(),
                Some(command_page::Body::Fact(fact)) => fact.payload.unwrap_or_default(),
                None => Any::default(),
            },
            trigger: trigger.clone(),
            index,
            correlation_id: correlation_id.clone(),
        })
        .collect()
}

/// `policy` as angzarr-router's table: each event type it handles (its
/// `EVENTS`, or every event of its source for a hand-written one) runs
/// [`Policy::on_event`] with the trigger's place and metadata, each command
/// for the target's stream at the root it names; and, for a policy that
/// answers refusals, each command type it translates (its `TRANSLATES`, or
/// every command of its target for a hand-written one) is answered by
/// [`Policy::on_refused`], with the refused command's context; either's
/// error is carried as the policy's failure. The kernel holds the answer
/// to the policy's one destination, the trigger's edition, a named root,
/// commands only and the trigger's correlation and identity
/// ([`check_reactions`]).
pub(crate) fn dispatch<P: Policy>(policy: P) -> PolicyDispatch {
    let policy = Arc::new(policy);
    let target = <P::Target as CommandTarget>::DOMAIN;
    let mut table = PolicyDispatch::new(P::NAME, <P::Source as EventSource>::DOMAIN, target);
    let events: Vec<String> = match P::EVENTS.is_empty() {
        true => <P::Source as EventSource>::event_types(),
        false => P::EVENTS.iter().map(TypeName::full_name).collect(),
    };
    for event_type in events {
        let policy = Arc::clone(&policy);
        table = table.on_event_with_context(&event_type, move |event, page| {
            let meta = page.meta.cloned().unwrap_or_default();
            let ctx = PolicyContext::new(
                EventRef {
                    stream: page.cover.cloned(),
                    sequence: page.sequence,
                },
                meta.correlation_id.unwrap_or_default(),
                meta.recorded_at.unwrap_or_default(),
            );
            let commands = policy
                .on_event(event, &ctx)
                .map_err(|failure| super::route::policy_failed(&failure))?
                .map_or_else(Vec::new, Commands::into_orders);
            Ok(commands
                .into_iter()
                .map(|(root, command)| CommandBook {
                    cover: Some(Cover {
                        domain: target.to_string(),
                        root: Some(root),
                        edition: None,
                    }),
                    page: Some(CommandPage {
                        body: Some(command_page::Body::Command(Command {
                            payload: Some(command),
                        })),
                        ..CommandPage::default()
                    }),
                    handling: None,
                })
                .collect())
        });
    }
    if P::ANSWERS_REFUSALS {
        let translated: Vec<String> = match P::TRANSLATES.is_empty() {
            true => <P::Target as CommandTarget>::command_types(),
            false => P::TRANSLATES.iter().map(TypeName::full_name).collect(),
        };
        for command_type in translated {
            let policy = Arc::clone(&policy);
            table = table.on_refused(&command_type, move |refusal, ctx| {
                policy
                    .on_refused(refusal, ctx)
                    .map_err(|failure| super::route::policy_failed(&failure))
            });
        }
    }
    table
}

